-- 20260806_seed_airports_data.sql
--
-- Airport identity seed data (144 rows), exported 2026-08-06 from the dev
-- airports table, which was seeded exclusively from Google Places by
-- scripts/seed-airports.mjs (todo #22). PROVENANCE: every coordinate is
-- Google-sourced at 6 decimals (coord_source='google_places'); terminal
-- inventories carry their own terminals_provenance. This is DATA WITH
-- PROVENANCE checked in as a migration — not hardcoded location guesses —
-- so the boot-time runner can bring a fresh prod DB to parity without a
-- manual seeding step (an auto-created but EMPTY airports table would render
-- every briefing as verified-empty "No major airports within 50 miles").
--
-- Idempotent: ON CONFLICT (iata) DO UPDATE refreshes identity fields;
-- terminals/terminals_provenance use COALESCE so a NULL here never wipes
-- richer terminal data enriched after this export.

ON CONFLICT (iata) DO UPDATE SET
  name = EXCLUDED.name,
  city = EXCLUDED.city,
  country = EXCLUDED.country,
  lat = EXCLUDED.lat,
  lng = EXCLUDED.lng,
  coord_source = EXCLUDED.coord_source,
  is_major = EXCLUDED.is_major,
  terminals = COALESCE(EXCLUDED.terminals, airports.terminals),
  terminals_provenance = COALESCE(EXCLUDED.terminals_provenance, airports.terminals_provenance),
  updated_at = now();
